// Edit only these three values. One execution starts one paid Actor run.
const keywords = [
  'best web scraping api',
  'google ai overview tracker',
  'seo api',
];
const locationCode = 2840;
const languageCode = 'en';

if (!Array.isArray(keywords) || keywords.some((keyword) => typeof keyword !== 'string')) {
  throw new Error('keywords must be an array of strings.');
}
const cleanedKeywords = [...new Set(keywords.map((keyword) => keyword.trim()).filter(Boolean))];
if (cleanedKeywords.length < 1 || cleanedKeywords.length > 100) {
  throw new Error('Provide 1–100 nonblank, unique keywords in one batch.');
}
if (!Number.isInteger(locationCode) || locationCode < 1 || locationCode > 100000000) {
  throw new Error('locationCode must be an integer from 1 to 100000000.');
}
if (typeof languageCode !== 'string' || !/^[a-z]{2,3}(?:-[A-Za-z]{2,4})?$/.test(languageCode.trim())) {
  throw new Error('Provide a valid Google language code, for example en, es, de, or fr.');
}
// Do not prefix formula-leading keywords here: the provider needs the original terms.
// Spreadsheet protection is applied only to the exported text after results return.
return [{ json: { keywords: cleanedKeywords, locationCode, languageCode: languageCode.trim() } }];

const responseItems = $input.all();
if (responseItems.length !== 1) {
  throw new Error('Expected one full HTTP response. Enable Include Response Headers and Status on the HTTP node.');
}
const response = responseItems[0].json;
if (!Number.isInteger(response.statusCode) || response.statusCode < 200 || response.statusCode >= 300) {
  throw new Error('The Apify request did not return a successful HTTP status.');
}
const rows = response.body;
if (!Array.isArray(rows)) {
  throw new Error('Expected an array of dataset rows in the HTTP response body.');
}
if (rows.length === 0) {
  throw new Error('No keyword rows returned. Check the Apify paid plan, run spending limit, and run log before retrying.');
}
if (rows.length > 100) {
  throw new Error('Unexpected result size: this workflow handles one batch of at most 100 keywords.');
}
const batch = $('Prepare keyword batch').first().json;
function spreadsheetText(value) {
  const text = value == null ? '' : String(value);
  return (/^\s*[=+\-@]/.test(text) || /^[\t\r\n]/.test(text)) ? "'" + text : text;
}
function numeric(value, field, index) {
  if (typeof value !== 'number' || !Number.isFinite(value) || value < 0) {
    throw new Error('Invalid ' + field + ' in result row ' + (index + 1) + '.');
  }
  return value;
}
return rows.map((row, index) => {
  if (!row || typeof row !== 'object' || Array.isArray(row) || row.status !== 'ANALYZED') {
    throw new Error('Result row ' + (index + 1) + ' was not analyzed. Inspect the run log before retrying; a report event may already have been charged.');
  }
  if (typeof row.input !== 'string' || !row.input.trim()
      || !row.metrics || typeof row.metrics !== 'object' || Array.isArray(row.metrics)
      || !Array.isArray(row.recommendations) || row.recommendations.some((value) => typeof value !== 'string')
      || typeof row.checkedAt !== 'string' || !Number.isFinite(Date.parse(row.checkedAt))) {
    throw new Error('Unexpected keyword result shape in row ' + (index + 1) + '.');
  }
  if (row.metrics.competition != null && typeof row.metrics.competition !== 'string') {
    throw new Error('Unexpected advertiser competition in row ' + (index + 1) + '.');
  }
  return { json: {
    keyword: spreadsheetText(row.input),
    locationCode: batch.locationCode,
    languageCode: spreadsheetText(batch.languageCode),
    searchVolume: numeric(row.metrics.searchVolume, 'search volume', index),
    cpc: numeric(row.metrics.cpc, 'CPC', index),
    advertiserCompetition: spreadsheetText(row.metrics.competition),
    advertiserCompetitionIndex: numeric(row.metrics.competitionIndex, 'advertiser competition index', index),
    researchPriorityScore: numeric(row.score, 'research-priority score', index),
    recommendation: spreadsheetText(row.recommendations.join(' | ')),
    checkedAt: spreadsheetText(row.checkedAt),
  } };
}).sort((a, b) => b.json.researchPriorityScore - a.json.researchPriorityScore
  || a.json.keyword.localeCompare(b.json.keyword));
